n=17;c=8
out=[]
for r in range(n):
    row=[0]*n
    # expanding 2 diagonals, reaching both edges at row 8
    if r<=c:
        row[c-r]=2; row[c+r]=2
    # 1 diagonals begin at row 3 within the expanding cone
    if r>=3:
        lo=max(0,c-r); hi=min(n-1,c+r)
        for x in range(lo,hi+1):
            if (x-r-2)%4==0 and row[x]==0:
                row[x]=1
    out.append(row)
out

